                }
            }
        }

        for (prev in 1..4) {
            for (up in 0..maxUp) {
                for (down in 0..maxDown) {
                    val count = dp[prev][up][down]
                    if (count == 0) continue
                    for (curr in 1..4) {
                        if (curr == prev) continue
                        var newUp = up
                        var newDown = down
                        // The previous previous value is not stored. 
                        // Wait, the state needs prev_prev and prev? 
                        // The condition for hump/valley is at index j (2..n-1).
                        // When adding y_i (current), the check is at j = i-1.
                        // We need y_{i-2}, y_{i-1}, y_i.
                        // My state dp[i][prev] means y_i = prev.
                        // I need y_{i-1} as well.
                        // Let's change state: dp[i][y_{i-1}][y_i][up][down]
                    }
                }
            }
        }
    }

    // Let's rethink the state.
    // dp[i][prev_prev][prev][up][down]
    // i is the length of sequence built so far. 
    // Indices: 1..i.
    // Next we add curr. 
    // The check for hump/valley happens at index i (which is prev).
    // Condition: y_{i-1} (prev_prev) < y_i (prev) > y_{i+1} (curr) -> hump
    // y_{i-1} > y_i < y_{i+1} -> valley

    // State: dp[prev_prev][prev][up][down]
    // Initialize for i=2: sequence y1, y2.
    var dp2 = Array(5) { Array(5) { Array(maxUp + 1) { IntArray(maxDown + 1) { 0 } } } }
    for (y1 in 1..4) {
        for (y2 in 1..4) {
            if (y1 != y2) {
                dp2[y1][y2][0][0] = 1
            }
        }
    }

    // Iterate i from 3 to n
    for (i in 3..n) {
        val nextDp2 = Array(5) { Array(5) { Array(maxUp + 1) { IntArray(maxDown + 1) { 0 } } } }
        for (pp in 1..4) { // y_{i-2}
            for (p in 1..4) { // y_{i-1}
                for (up in 0..maxUp) {
                    for (down in 0..maxDown) {
                        val cnt = dp2[pp][p][up][down]
                        if (cnt == 0) continue
                        for (c in 1..4) { // y_i
                            if (c == p) continue
                            var nup = up
                            var ndown = down
                            // Check hump/valley at index i-1 (value p)
                            // neighbors: pp, p, c
                            if (pp < p && p > c) {
                                nup++
                            } else if (pp > p && p < c) {
                                ndown++
                            }
                            if (nup <= maxUp && ndown <= maxDown) {
                                nextDp2[p][c][nup][ndown] += cnt
                            }
                        }
                    }
                }
            }
        }
        dp2 = nextDp2
    }

    var ans = 0L
    for (pp in 1..4) {
        for (p in 1..4) {
